SELECT m.id AS id, m.user_id AS user_id, u.name AS author_name, u.avatar AS avatar, u.role AS role, m.content AS content, m.ip AS ip, m.province AS province, m.created_at AS created_at FROM t_message m LEFT JOIN t_user u ON u.id = m.user_id
m.user_id = #{userId}
ORDER BY m.created_at DESC, m.id DESC
